hours = []
rooms = []
sessions = []
try:
	day = str(props.get("day") or "Thu").strip()
	start = int(number(props.get("start_hour"), 9))
	end = int(number(props.get("end_hour"), 13))
	if end <= start:
		end = start + 1
	link = str(props.get("link") or "programme").strip()
	window_start = start * 60
	window_end = end * 60
	slots = (window_end - window_start) // 5
	names = as_list(props.get("rooms"))
	cols = {}
	for i in range(len(names)):
		rooms.append({"name": names[i].strip(), "at": str(i + 1)})
		cols[names[i].strip().lower()] = i + 1
	for h in range(start, end + 1):
		last = h == end
		hours.append({"label": clock(h * 60), "at": str((h - start) * 12 + (1 if last else 2)), "end": "true" if last else "false"})
	for raw in as_list(props.get("sessions")):
		parts = split_row(raw, 7)
		if parts[0].lower() != day.lower():
			continue
		begin = minutes(parts[1])
		finish = minutes(parts[2])
		if begin < 0 or finish <= begin or finish <= window_start or begin >= window_end:
			continue
		place = parts[3]
		if place.lower() in ["", "all", "every room", "everywhere"]:
			lane = "1 / " + str(len(rooms) + 1)
			where = "every room"
		elif place.lower() in cols:
			lane = str(cols[place.lower()])
			where = place
		else:
			continue
		kind = parts[6].lower()
		if kind not in ["talk", "workshop", "social", "break"]:
			kind = "talk"
		shown_begin = max(begin, window_start)
		shown_end = min(finish, window_end)
		sessions.append({
			"title": parts[4],
			"kind": kind,
			"a": str((shown_begin - window_start) // 5 + 1),
			"b": str((shown_end - window_start) // 5 + 1),
			"lane": lane,
			"href": link + "#" + anchor(day, parts[1], place, slugify),
			"label": parts[4] + ", " + clock(begin) + " to " + clock(finish) + ", " + where,
		})
	component.span = str(slots)
	component.lanes = str(max(1, len(rooms)))
	component.hours_n = str(end - start)
except:
	component.span = "48"
	component.lanes = "2"
	component.hours_n = "4"
component.hours = hours
component.rooms = rooms
component.sessions = sessions
